import urllib.request
import urllib.error
import time


class RateLimitError(Exception):
    pass


class ServerError(Exception):
    pass


class ClientError(Exception):
    pass


class ConnectionError(Exception):
    pass


class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        retries_429 = 3
        backoff_times = [0.5, 1, 2]

        # Handle 429 retries
        for i in range(retries_429):
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                return response.read().decode('utf-8')
            except urllib.error.HTTPError as e:
                if e.code == 429:
                    if i < retries_429 - 1:
                        time.sleep(backoff_times[i])
                        continue
                    else:
                        raise RateLimitError(f"HTTP 429 after {retries_429} retries: {e.reason}")
                elif e.code >= 500:
                    # Server error: retry once after 1s
                    time.sleep(1)
                    try:
                        req = urllib.request.Request(url)
                        response = urllib.request.urlopen(req, timeout=self.timeout)
                        return response.read().decode('utf-8')
                    except urllib.error.HTTPError as e2:
                        if e2.code >= 500:
                            raise ServerError(f"HTTP {e2.code} after retry: {e2.reason}")
                        else:
                            raise e2
                    except urllib.error.URLError as e2:
                        raise ConnectionError(f"ConnectionError after retry: {e2.reason}")
                elif e.code >= 400:
                    raise ClientError(f"HTTP {e.code}: {e.reason}")
                else:
                    raise
            except urllib.error.URLError as e:
                # Network error: retry once after 1s
                time.sleep(1)
                try:
                    req = urllib.request.Request(url)
                    response = urllib.request.urlopen(req, timeout=self.timeout)
                    return response.read().decode('utf-8')
                except urllib.error.URLError as e2:
                    raise ConnectionError(f"ConnectionError after retry: {e2.reason}")
                except urllib.error.HTTPError as e2:
                    if e2.code == 429:
                        raise RateLimitError(f"HTTP 429: {e2.reason}")
                    elif e2.code >= 500:
